const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const won=n=>Number(n||0).toLocaleString('ko-KR')+'원';
const discountRate=id=>20+((Math.imul(Number(id)|0,2654435761)>>>0)%11);
const salePrice=(original,id)=>{const step=original<1000?10:100,min=Math.ceil(original*.7/step)*step,max=Math.floor(original*.8/step)*step,rounded=Math.round(original*(100-discountRate(id))/100/step)*step;return Math.max(step,Math.min(max,Math.max(min,rounded)))};
const SET_DISCOUNT_RATE=10;
const setPriceDiscount=subtotal=>subtotal?Math.min(subtotal,Math.max(10,Math.round(subtotal*SET_DISCOUNT_RATE/1000)*10)):0;
const day=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const shops=window.SEOUL_SHOPS;
const SURPLUS_REASONS=['오늘 준비한 여분','예약 취소로 남은 준비분','마감 전 남은 판매분'];
const samples=window.SEOUL_MENU_DEFS.map(([id,shop,name,originalPrice,stock,image,desc],i)=>({id,shop,name,originalPrice,discountRate:discountRate(id),price:salePrice(originalPrice,id),stock,image:'assets/'+image+'.jpg',desc,surplusReason:SURPLUS_REASONS[(id*5)%SURPLUS_REASONS.length],closing:shops.find(s=>s.id===shop)?.category?(id%3===0?'20:00':'21:00'):'18:00',date:day(),publishedAt:Date.parse(day()+'T00:00:00+09:00')+(window.SEOUL_MENU_DEFS.length-i)*60000,likes:0,sample:true}));
const home={lat:37.5446,lng:127.0559}; // 성수역 기본 위치
const saved=(()=>{try{return JSON.parse(localStorage.getItem('hangolmok-v2')||'null')}catch{return null}})();
const old=(()=>{try{return JSON.parse(localStorage.getItem('hangolmok-v1')||'null')}catch{return null}})();
let state=saved||{mode:'guest',tab:'feed',font:1,menus:old?.menus?.length?old.menus.map(m=>({...m,closing:m.closing||'18:00',sample:!m.custom})):samples.map(m=>({...m})),likes:old?.liked||[],orders:[],cart:[],location:null,locationStatus:'demo'};
state.menus=Array.isArray(state.menus)?state.menus:samples;
state.likes=Array.isArray(state.likes)?state.likes:[];
state.orders=Array.isArray(state.orders)?state.orders:[];
state.customerHiddenOrderIds=Array.isArray(state.customerHiddenOrderIds)?state.customerHiddenOrderIds:[];
state.ownerHiddenOrderIds=Array.isArray(state.ownerHiddenOrderIds)?state.ownerHiddenOrderIds:[];
state.orderStatuses=state.orderStatuses&&typeof state.orderStatuses==='object'?state.orderStatuses:{};
state.orderCompletedAt=state.orderCompletedAt&&typeof state.orderCompletedAt==='object'?state.orderCompletedAt:{};
state.demoOwnerOrders=Array.isArray(state.demoOwnerOrders)?state.demoOwnerOrders:null;
state.cart=Array.isArray(state.cart)?state.cart:[];
state.cartSet=Array.isArray(state.cartSet)?state.cartSet:null;
state.font=Number(state.font)||1;
const DATA_VERSION=7;let migrated=false;
if(state.seedVersion!==DATA_VERSION||!state.menus.some(m=>m.date===day())){const custom=state.menus.filter(m=>!m.sample&&m.date===day()).map(m=>{const priced=m.originalPrice?m:{...m,originalPrice:m.price,discountRate:discountRate(m.id),price:salePrice(m.price,m.id)};return {...priced,surplusReason:priced.surplusReason||SURPLUS_REASONS[0]}});state.menus=[...custom,...samples.map(m=>({...m}))];state.cart=[];state.cartSet=null;state.seedVersion=DATA_VERSION;migrated=true;}
state.area=state.area||'';
let kakaoMap=null,pickupMapView=null;let storyFilter='',settingsOpen=false;let feedQuery='',mapQuery='',aiText='',aiResult=null,draft=null,photo=null,selectedShop=null,recognition=null,lastViewKey=null;
const motionAllowed=()=>!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
const revealObserver=typeof IntersectionObserver==='function'?new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target)}})},{rootMargin:'0px 0px 40px 0px',threshold:.08}):null;
function revealCards(){if(!motionAllowed()||!revealObserver)return;document.querySelectorAll('.main .post,.main .owner-order-card,.main .manage-item,.main .map-list .shop-row').forEach((el,i)=>{el.classList.add('reveal-ready');el.style.setProperty('--reveal-delay',Math.min(i,5)*45+'ms');revealObserver.observe(el)})}
const persist=()=>{try{localStorage.setItem('hangolmok-v2',JSON.stringify(state))}catch{toast('이 기기의 저장 공간이 부족합니다.')}};
if(migrated)persist();
const shop=id=>shops.find(s=>s.id===id)||shops[0];
const active=()=>state.menus.filter(m=>m.date===day());
const discountPercent=m=>Math.round((1-m.price/(m.originalPrice||m.price))*100);
const OWNER_SHOP_ID='bake';
const ownerMenus=()=>active().filter(m=>m.shop===OWNER_SHOP_ID);
const orderNumber=o=>String(o.id).slice(-6);
const ownerOrders=()=>[...state.orders.filter(o=>o.items.some(i=>i.shop===OWNER_SHOP_ID)),...state.demoOwnerOrders].filter(o=>!state.ownerHiddenOrderIds.includes(o.id)).sort((a,b)=>b.id-a.id);
const orderStatus=o=>state.orderStatuses[o.id]||'waiting';
const statusLabel=s=>({waiting:'접수 대기',accepted:'주문 수락',preparing:'준비 중',ready:'준비 완료',completed:'픽업 완료'})[s]||'접수 대기';
const customerOrderDone=o=>o.stops.length>0&&o.stops.every(s=>s.id===OWNER_SHOP_ID&&orderStatus(o)==='completed');
function ownerBanner(){const s=shop(OWNER_SHOP_ID);return `<div class="owner-shop-banner"><img src="assets/${s.image}.jpg" alt=""><span><strong>${esc(s.name)}</strong><small>${esc(s.area)} · 내 가게</small></span></div>`}
const image=m=>esc(m.image||'assets/croissant.jpg');
const distance=(a,b)=>{const r=Math.PI/180,x=(b.lat-a.lat)*r,y=(b.lng-a.lng)*r,z=Math.sin(x/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(y/2)**2;return 6371*2*Math.atan2(Math.sqrt(z),Math.sqrt(1-z))};
const center=()=>state.area&&state.area!=='all'?shop(state.area):state.location||home;
const nearby=()=>state.area==='all'?shops:shops.filter(s=>distance(center(),s)<=3);
const nearbyMenus=()=>active().filter(m=>nearby().some(s=>s.id===m.shop));
const hhmm=d=>new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false}).format(d);
if(!state.demoOwnerOrders){const now=Date.now(),demoPrice=id=>samples.find(m=>m.id===id)?.price||0;state.demoOwnerOrders=[{id:now-120000,date:day()+' '+hhmm(new Date(now-120000)),items:[{id:1,shop:OWNER_SHOP_ID,name:'딸기 크루아상',qty:2,price:demoPrice(1)},{id:61,shop:OWNER_SHOP_ID,name:'성수 소금빵',qty:1,price:demoPrice(61)}],total:demoPrice(1)*2+demoPrice(61),stops:[{id:OWNER_SHOP_ID,name:'오후의 빵집',address:shop(OWNER_SHOP_ID).address,pickup:hhmm(new Date(now+24*60000)),items:['딸기 크루아상 × 2','성수 소금빵 × 1']}],sample:true},{id:now-300000,date:day()+' '+hhmm(new Date(now-300000)),items:[{id:4,shop:OWNER_SHOP_ID,name:'버터 스콘',qty:1,price:demoPrice(4)},{id:64,shop:OWNER_SHOP_ID,name:'초코 휘낭시에',qty:2,price:demoPrice(64)}],total:demoPrice(4)+demoPrice(64)*2,stops:[{id:OWNER_SHOP_ID,name:'오후의 빵집',address:shop(OWNER_SHOP_ID).address,pickup:hhmm(new Date(now+18*60000)),items:['버터 스콘 × 1','초코 휘낭시에 × 2']}],sample:true}];persist()}
const icon=name=>{
 const paths={
  feed:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  map:'<path d="M3 6 9 3l6 3 6-3v15l-6 3-6-3-6 3V6Z"/><path d="M9 3v15M15 6v15"/>',
  orders:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2V3Z"/><path d="M9 8h6M9 12h6"/>',
  register:'<path d="M12 4v16M4 12h16"/>',
  ownerOrders:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2V3Z"/><path d="M9 8h6M9 12h6"/>',
  manage:'<path d="M4 6h16M4 12h16M4 18h16"/>'
 };
 return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.feed}</svg>`
};
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),3300)}
function say(t){if(!window.speechSynthesis){toast('이 브라우저는 음성 안내를 지원하지 않습니다.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='ko-KR';u.rate=.9;speechSynthesis.speak(u)}
function pageSpeech(){
 const titles={feed:'피드',map:'지도',orders:'내 주문',register:'등록',ownerOrders:'주문',manage:'관리'};
 const parts=[titles[state.tab]+' 화면입니다.'];
 if(state.tab==='feed'){const items=visibleFeed();parts.push((state.area==='all'?'서울 전체 메뉴 ':'근처 메뉴 ')+items.length+'개.');parts.push(...items.slice(0,6).map(m=>shop(m.shop).name+'의 '+m.name+', '+won(m.price)+', 재고 '+m.stock+'개.'))}
 if(state.tab==='map'){const list=visibleMapShops();parts.push((state.area==='all'?'서울 전체 가게 ':'반경 3킬로미터 내 가게 ')+list.length+'곳.');parts.push(...list.map(s=>state.area==='all'?s.area+'의 '+s.name+'.':s.name+', 약 '+distance(center(),s).toFixed(1)+'킬로미터.'))}
 if(state.tab==='orders'){parts.push('진행 중인 주문 '+state.orders.filter(o=>!customerOrderDone(o)).length+'건, 완료 내역 '+state.orders.filter(customerOrderDone).length+'건.');parts.push(...state.orders.slice(0,3).map(o=>statusLabel(orderStatus(o))+' 주문, '+won(o.total)+', '+o.stops.length+'곳 픽업.'))}
 if(state.tab==='register')parts.push('먼저 사진을 촬영하거나 올리고, 상품의 이름, 가격, 재고량, 마감 시간을 말해 주세요. 초안을 확인한 다음 등록할 수 있습니다.');
 if(state.tab==='ownerOrders')parts.push('오후의 빵집 진행 중인 주문 '+ownerOrders().filter(o=>orderStatus(o)!=='completed').length+'건, 완료 내역 '+ownerOrders().filter(o=>orderStatus(o)==='completed').length+'건. 주문을 수락하고 준비한 뒤 픽업 완료로 처리할 수 있습니다.');
 if(state.tab==='manage'){parts.push('오후의 빵집 오늘의 메뉴 '+ownerMenus().length+'개.');parts.push(...ownerMenus().slice(0,7).map(m=>m.name+', '+won(m.price)+', 재고 '+m.stock+'개.'))}
 say(parts.join(' '))
}
function render(){document.documentElement.style.setProperty('--scale',state.font);const owner=state.mode==='owner';const tabs=owner?[['register','등록'],['ownerOrders','주문'],['manage','관리']]:[['feed','피드'],['map','지도'],['orders','내 주문']];if(!tabs.some(([id])=>id===state.tab))state.tab=owner?'register':'feed';const viewKey=state.mode+':'+state.tab,entering=viewKey!==lastViewKey;lastViewKey=viewKey;
 $('#app').innerHTML=`<div class="site"><header class="site-header"><div class="header-main"><button class="brand" data-action="home" aria-label="마감한끼 홈"><span class="brand-mark">ㅎ</span><span>마감한끼</span></button><div class="header-actions"><div class="settings-menu"><button class="settings-button" data-action="settings" aria-label="설정" aria-expanded="${settingsOpen}" aria-controls="settings-panel"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3.5 13.3 5l2-.3.7 1.8 1.9.8-.3 2 1.5 1.2-1 1.8 1 1.8-1.5 1.2.3 2-1.9.8-.7 1.8-2-.3L12 21l-1.3-1.5-2 .3-.7-1.8-1.9-.8.3-2L4.9 14l1-1.8-1-1.8 1.5-1.2-.3-2L8 6.5l.7-1.8 2 .3L12 3.5Z"/><circle cx="12" cy="12.2" r="2.6"/></svg><span>설정</span></button><div id="settings-panel" class="settings-panel" role="group" aria-label="접근성 설정" ${settingsOpen?'':'hidden'}><strong>접근성 설정</strong><div class="settings-row"><span>글자 크기</span><div class="font-tools" aria-label="글자 크기 조절"><button data-action="font-down" aria-label="글자 작게">가−</button><button data-action="font-up" aria-label="글자 크게">가＋</button></div></div><button class="voice-btn" data-action="speak" aria-label="현재 화면 음성 안내">◖)) <span>현재 화면 음성 안내</span></button></div></div><button class="mode-switch" data-action="mode">${owner?'손님 ver':'사장 ver'} <span aria-hidden="true">↗</span></button></div></div></header><main id="main" class="main ${state.tab}${entering?' page-enter':''}">${content()}</main><nav class="tabbar" aria-label="${owner?'사장님 메뉴':'손님 메뉴'}">${tabs.map(([id,label])=>`<button data-action="tab" data-value="${id}" class="${state.tab===id?'active':''}" aria-current="${state.tab===id?'page':'false'}"><span class="tab-icon" aria-hidden="true">${icon(id)}</span><span>${label}</span></button>`).join('')}</nav></div>`;if(entering)revealCards();if(state.tab==='map')requestAnimationFrame(initMap);if(state.tab==='feed')requestAnimationFrame(restoreShopCarousels)}
function heading(kicker,title,sub=''){return `<div class="page-heading"><span class="kicker">${kicker}</span><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>`}
function content(){return ({feed:feedPage,map:mapPage,orders:ordersPage,register:registerPage,ownerOrders:ownerOrdersPage,manage:managePage})[state.tab]()}
function locationNote(){
 const areas=[...new Map(shops.map(s=>[s.area,s])).values()];
 return `<div class="location-note"><div class="location-actions"><label class="area-select-label">지역 보기<select id="area-select" aria-label="서울 지역 선택"><option value="" ${!state.area?'selected':''}>내 주변 3km</option><option value="all" ${state.area==='all'?'selected':''}>서울 전체</option>${areas.map(s=>`<option value="${s.id}" ${state.area===s.id?'selected':''}>${esc(s.area)}</option>`).join('')}</select></label><button data-action="locate">내 위치 사용</button></div></div>`
}
const feedLocation=()=>state.locationStatus==='live'&&state.location?state.location:home;
function visibleFeed(){const origin=feedLocation();return nearbyMenus().filter(m=>!storyFilter||m.shop===storyFilter).filter(m=>(m.name+' '+m.desc+' '+shop(m.shop).name).toLocaleLowerCase().includes(feedQuery.toLocaleLowerCase())).sort((a,b)=>distance(origin,shop(a.shop))-distance(origin,shop(b.shop))||(b.publishedAt||0)-(a.publishedAt||0)||a.id-b.id)}
function visibleShopGroups(){const groups=new Map();for(const m of visibleFeed()){if(!groups.has(m.shop))groups.set(m.shop,[]);groups.get(m.shop).push(m)}return [...groups].map(([id,menus])=>({shop:shop(id),menus}))}
function productTile(m){const liked=state.likes.includes(m.id),inCart=state.cart.some(x=>x.id===m.id);return `<div class="shop-product"><img class="shop-product-photo" src="${image(m)}" alt="${esc(m.name)} 사진" loading="lazy"><div class="shop-product-body"><strong class="shop-product-name" title="${esc(m.name)}">${esc(m.name)}</strong><span class="shop-product-price"><b>${won(m.price)}</b><del>${won(m.originalPrice||m.price)}</del></span><small class="shop-product-stock">${discountPercent(m)}% 할인 · ${m.stock?'재고 '+m.stock+'개':'품절'}</small><p class="shop-product-desc" title="${esc(m.desc)}">${esc(m.desc)}</p><div class="shop-product-actions"><button data-action="like" data-id="${m.id}" class="shop-like ${liked?'liked':''}" aria-pressed="${liked}" aria-label="${esc(m.name)} 좋아요">${liked?'♥':'♡'} <span>${(m.likes||0)+(liked?1:0)}</span></button><button data-action="add" data-id="${m.id}" class="shop-add" ${!m.stock?'disabled':''} aria-label="${esc(m.name)} 담기">${inCart?'더 담기':'담기 ＋'}</button></div></div></div>`}
function shopCard(group){const s=group.shop,menus=group.menus;return `<article class="post shop-post"><div class="post-top"><img src="assets/${s.image}.jpg" alt=""><span><strong>${esc(s.name)}</strong><small>${esc(s.area)} · ${esc(s.category||'골목 가게')}</small><em class="feed-distance">${state.locationStatus==='live'?'내 위치':'성수역'}에서 ${distance(feedLocation(),s).toFixed(1)}km</em></span><span class="stock">메뉴 ${menus.length}개</span></div><div class="shop-carousel-head"><strong>오늘의 마감 메뉴</strong><small>${menus.length>3?'좌우로 넘겨 보세요':'메뉴 사진을 둘러보세요'}</small></div><div class="shop-carousel-wrap"><div class="shop-products" data-shop="${esc(s.id)}" aria-label="${esc(s.name)} 메뉴, 좌우로 스크롤">${menus.map(productTile).join('')}</div>${menus.length>3?'<button class="shop-products-prev" data-action="shop-products-prev" aria-label="이전 메뉴 보기" disabled>‹</button><button class="shop-products-next" data-action="shop-products-next" aria-label="다음 메뉴 보기">›</button>':''}</div></article>`}
const carouselPositions=new Map();
function updateShopCarouselArrows(rail){const wrap=rail?.closest('.shop-carousel-wrap');if(!wrap)return;const prev=wrap.querySelector('.shop-products-prev'),next=wrap.querySelector('.shop-products-next');if(prev)prev.disabled=rail.scrollLeft<=2;if(next)next.disabled=rail.scrollLeft+rail.clientWidth>=rail.scrollWidth-2}
function restoreShopCarousels(){document.querySelectorAll('.shop-products').forEach(rail=>{rail.scrollLeft=carouselPositions.get(rail.dataset.shop)||0;updateShopCarouselArrows(rail)})}
function stories(){
 const latest=s=>Math.max(0,...active().filter(m=>m.shop===s.id).map(m=>m.publishedAt||(!m.sample&&Number(m.id)>1e12?Number(m.id):0)));
 const list=nearby().slice().sort((a,b)=>latest(b)-latest(a));
 requestAnimationFrame(updateStoryArrows);
 return `<div class="stories-heading"><strong>최근 재고 등록 매장</strong><span>왼쪽부터 최신 등록순</span></div><div class="stories-wrap"><div class="stories" aria-label="최근 재고 등록 매장, 최신 등록순, 좌우로 스크롤">${list.map((s,i)=>`<button class="story ${storyFilter===s.id?'active':''}" data-action="story" data-value="${s.id}"><span class="story-ring"><img src="assets/${s.image}.jpg" alt="">${i===0?'<em class="story-new">최신</em>':''}</span><span>${esc(s.name)}</span></button>`).join('')}<button class="story ${!storyFilter?'active':''}" data-action="story" data-value=""><span class="story-ring"><span class="story-all">◎</span></span><span>전체</span></button></div><button class="stories-prev" data-action="stories-prev" aria-label="이전 가게 보기" disabled>‹</button><button class="stories-next" data-action="stories-next" aria-label="다음 가게 보기">›</button></div><div class="feed-meta"><span>오늘의 메뉴</span><strong>${visibleFeed().length}개</strong></div>`
}
function feedPage(){return `<div class="feed-head"><button class="ai-button" data-action="ai-open">✧ 골목 세트</button></div><label class="search-field"><span aria-hidden="true">⌕</span><input id="feed-search" type="search" placeholder="원하는 메뉴나 가게 검색" value="${esc(feedQuery)}" aria-label="메뉴 검색"></label>${locationNote()}${stories()}<div class="feed-list">${visibleShopGroups().map(shopCard).join('')||`<div class="empty"><h2>표시할 메뉴가 없어요</h2><p>${state.locationStatus==='live'?'현재 위치에서 3km 이내의 등록된 샘플 가게가 없습니다.':'검색어를 바꾸거나 내 위치를 확인해 주세요.'}</p></div>`}</div>${state.cart.length?`<button class="floating-cart" data-action="cart">담은 메뉴 ${state.cart.reduce((n,x)=>n+x.qty,0)}개 · ${won(cartTotal())} <span>보기 →</span></button>`:''}<p class="demo-note">서울 전역의 가상 가게 ${shops.length}곳과 샘플 메뉴 ${samples.length}개를 사용하는 시연 화면입니다. 가격과 재고는 이 기기에만 저장됩니다.</p>`}
function visibleMapShops(){return nearby().filter(s=>{const q=mapQuery.toLocaleLowerCase();return !q||s.name.toLocaleLowerCase().includes(q)||active().some(m=>m.shop===s.id&&m.name.toLocaleLowerCase().includes(q))})}
function mapPage(){const c=center(),markers=visibleMapShops().map(s=>{const x=50+(s.lng-c.lng)*750,y=50-(s.lat-c.lat)*750;return `<button class="map-pin" data-action="shop" data-value="${s.id}" style="left:${Math.max(9,Math.min(91,x))}%;top:${Math.max(12,Math.min(87,y))}%" aria-label="${esc(s.name)} 정보">●<span>${esc(s.name)}</span></button>`}).join('');return `${heading('AROUND ME','서울 골목 지도',state.area==='all'?'서울 전역의 가상 가게 20곳을 둘러보세요.':'선택한 위치에서 반경 3km 안의 가게를 찾아보세요.')}<label class="search-field"><span aria-hidden="true">⌕</span><input id="map-search" type="search" placeholder="지도에서 메뉴 검색" value="${esc(mapQuery)}" aria-label="지도 메뉴 검색"></label>${locationNote()}<div class="map-canvas" role="group" aria-label="내 위치와 근처 가게를 표시한 안내 지도"><div class="street horizontal h1"></div><div class="street horizontal h2"></div><div class="street horizontal h3"></div><div class="street vertical v1"></div><div class="street vertical v2"></div><div class="street diagonal"></div><div class="radius-ring"></div><div id="kakao-map" class="kakao-map"></div><div class="you-pin" style="left:50%;top:50%" title="내 위치 또는 성수역 기본 위치">⌖<span>내 위치</span></div>${markers}<span class="map-attrib">위치 관계 안내 · 실제 지도 아님</span></div><div class="map-list"><h2>${state.area==='all'?'서울 전체':'3km 이내'} 가게 <span>${visibleMapShops().length}곳</span></h2>${visibleMapShops().map(s=>`<button data-action="shop" data-value="${s.id}" class="shop-row"><img src="assets/${s.image}.jpg" alt=""><span><strong>${esc(s.name)}</strong><small>${state.area==='all'?esc(s.area):distance(c,s).toFixed(1)+'km'} · 오늘 메뉴 ${active().filter(m=>m.shop===s.id).length}개</small></span><b>›</b></button>`).join('')||'<p class="muted">반경 안에 표시할 샘플 가게가 없습니다.</p>'}</div><p class="demo-note">서울 곳곳의 가상 가게와 예시 위치입니다. 실제 길찾기는 추후 연결됩니다.</p>`}
function ordersPage(){const likedShops=[...new Set(active().filter(m=>state.likes.includes(m.id)).map(m=>m.shop))],visibleOrders=state.orders.filter(o=>!state.customerHiddenOrderIds.includes(o.id)),ongoing=visibleOrders.filter(o=>!customerOrderDone(o)),done=visibleOrders.filter(customerOrderDone);return `${heading('MY ALLEY','내 주문','주문 현황과 좋아하는 가게를 확인하세요.')}<section class="panel"><div class="panel-title"><h2>진행 중인 주문</h2><span>${ongoing.length}건</span></div>${ongoing.length?ongoing.map(orderCard).join(''):'<div class="empty small"><h3>진행 중인 주문이 없어요</h3><p>피드에서 메뉴를 담아 주문 흐름을 체험해 보세요.</p><button class="plain-button" data-action="tab" data-value="feed">피드로 가기 →</button></div>'}</section><section class="panel"><div class="panel-title"><h2>완료 내역</h2><span>${done.length}건</span></div>${done.length?done.map(orderCard).join(''):'<p class="muted">픽업이 완료된 주문이 여기에 모여요.</p>'}</section><section class="panel"><div class="panel-title"><h2>좋아요 남긴 가게</h2><span>${likedShops.length}곳</span></div>${likedShops.length?likedShops.map(id=>{const s=shop(id);return `<button class="shop-row" data-action="shop" data-value="${id}"><img src="assets/${s.image}.jpg" alt=""><span><strong>${esc(s.name)}</strong><small>좋아요 남긴 메뉴 ${active().filter(m=>m.shop===id&&state.likes.includes(m.id)).length}개</small></span><b>›</b></button>`}).join(''):'<p class="muted">좋아요를 누른 가게가 여기에 모여요.</p>'}</section><section class="panel review-panel"><h2>다녀온 골목, 어땠나요?</h2><p>방문 경험을 남기는 리뷰 기능은 추후 제공됩니다.</p><button class="outline-button" data-action="review">리뷰 작성하기</button></section>`}
function orderItemRows(items){return items.map(i=>`<div class="order-price-row"><span><strong>${esc(i.name)}</strong><small>개당 ${won(i.price)} × ${i.qty}개</small></span><b>${won(i.price*i.qty)}</b></div>`).join('')}
function orderCard(o){const bakery=o.items.some(i=>i.shop===OWNER_SHOP_ID),done=customerOrderDone(o),status=done?'픽업 완료':bakery&&orderStatus(o)==='completed'?'일부 가게 픽업 완료':bakery?statusLabel(orderStatus(o)):'픽업 대기';return `<div class="order-card"><div class="order-top"><strong>주문 #${orderNumber(o)}</strong><span>${status} · 데모</span></div><div class="order-price-items">${orderItemRows(o.items)}</div>${o.setDiscount?`<div class="cart-breakdown set-discount"><span>골목 응원 할인</span><strong>−${won(o.setDiscount)}</strong></div>`:''}<div class="order-price-total"><span>주문 총 가격</span><strong>${won(o.total)}</strong></div><div class="order-bottom"><small>${esc(done?state.orderCompletedAt[o.id]||o.date:o.date)} · ${o.stops.length}곳 픽업</small><button data-action="route" data-id="${o.id}">${done?'픽업 내역 보기':'지도에서 픽업 동선 보기'} →</button></div><button class="delete-order-button" data-action="delete-order" data-id="${o.id}" aria-label="주문 #${orderNumber(o)} 내역 삭제">내역 삭제</button></div>`}
function ownerOrdersPage(){const list=ownerOrders(),ongoing=list.filter(o=>orderStatus(o)!=='completed'),done=list.filter(o=>orderStatus(o)==='completed'),waiting=ongoing.filter(o=>orderStatus(o)==='waiting').length;return `${heading('FOR SHOP OWNERS','들어온 주문',`오후의 빵집 진행 중 ${ongoing.length}건 · 수락 대기 ${waiting}건`)}${ownerBanner()}<section class="panel"><div class="panel-title"><h2>진행 중인 주문</h2><span>${ongoing.length}건</span></div>${ongoing.length?ongoing.map(ownerOrderCard).join(''):'<div class="empty small"><h3>진행 중인 주문이 없어요</h3><p>새 주문이 들어오면 여기에 표시됩니다.</p></div>'}</section><section class="panel"><div class="panel-title"><h2>완료 내역</h2><span>${done.length}건</span></div>${done.length?done.map(ownerOrderCard).join(''):'<p class="muted">픽업 완료로 처리한 주문이 여기에 모여요.</p>'}</section><p class="demo-note">예시 주문은 시연용입니다. 실제 주문과 상태 변경은 이 브라우저에만 저장됩니다.</p>`}
function ownerOrderCard(o){const items=o.items.filter(i=>i.shop===OWNER_SHOP_ID),shopDiscount=items.reduce((sum,i)=>sum+(i.setDiscount||0),0),shopTotal=items.reduce((sum,i)=>sum+i.price*i.qty,0)-shopDiscount,stop=o.stops.find(s=>s.id===OWNER_SHOP_ID),status=orderStatus(o),done=status==='completed',next={waiting:['accepted','주문 수락'],accepted:['ready','준비 완료'],preparing:['ready','준비 완료'],ready:['completed','픽업 완료']}[status];return `<article class="owner-order-card"><div class="owner-order-top"><strong>주문 #${orderNumber(o)}</strong><span class="owner-status ${status}">${statusLabel(status)}</span></div><small>${esc(o.date)}${o.sample?' · 예시 주문':''}</small><div class="owner-order-items">${orderItemRows(items)}</div>${shopDiscount?`<div class="cart-breakdown set-discount"><span>골목 응원 할인</span><strong>−${won(shopDiscount)}</strong></div>`:''}<div class="order-price-total"><span>이 가게 총 가격</span><strong>${won(shopTotal)}</strong></div><div class="owner-eta"><span>${done?'픽업 완료 시간':'고객 도착 예상'}</span><strong>${esc(done?state.orderCompletedAt[o.id]||'완료':stop?.pickup||'확인 중')}</strong></div>${next?`<button class="primary owner-order-action" data-action="owner-status" data-id="${o.id}" data-value="${next[0]}">${next[1]}</button>`:'<p class="owner-ready">픽업 완료 내역에 보관 중입니다.</p>'}<button class="delete-order-button" data-action="delete-order" data-id="${o.id}" aria-label="주문 #${orderNumber(o)} 내역 삭제">내역 삭제</button></article>`}
function registerPage(){return `${heading('FOR SHOP OWNERS','오늘의 메뉴 등록','오후의 빵집에 새 메뉴를 등록하세요.')}${ownerBanner()}<section class="panel register-panel"><h2>1. 상품 사진</h2><p>사진을 촬영하거나 기기에서 올려 주세요.</p><label class="upload-box"><input id="product-photo" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" aria-label="상품 사진 촬영 또는 업로드">${photo?`<img src="${photo}" alt="선택한 상품 사진"><strong>사진을 선택했어요 · 다시 선택 가능</strong>`:'<span class="camera-icon">▣</span><strong>촬영 또는 사진 올리기</strong><small>JPG, PNG, WebP · 최대 5MB</small>'}</label><h2>2. 상품 정보</h2><p>예: “예약 취소로 남은 딸기 크루아상 4,500원, 3개 남았고 오후 6시에 마감해요.”</p><div class="voice-input"><button data-action="dictate" class="mic-button" aria-label="음성 입력 시작">🎙 <span>음성으로 입력</span></button><span id="mic-status">마이크가 어려우면 아래에 직접 입력해 주세요.</span></div><textarea id="product-phrase" rows="4" placeholder="상품 이름, 가격, 남은 수량, 재고가 생긴 이유, 마감시간을 말하거나 입력하세요."></textarea><button class="primary" data-action="make-draft">등록 초안 만들기 →</button><p class="demo-note">현재 입력 분석은 규칙 기반 데모입니다. 추출 결과를 사장님이 확인하고 수정한 뒤 등록합니다.</p></section>`}
function managePage(){return `${heading('FOR SHOP OWNERS','등록 메뉴 관리','오후의 빵집 메뉴 가격과 재고를 수정하세요.')}${ownerBanner()}<div class="panel"><div class="panel-title"><h2>오늘의 메뉴</h2><span>${ownerMenus().length}개</span></div>${ownerMenus().map(m=>`<div class="manage-item"><img src="${image(m)}" alt=""><div><strong>${esc(m.name)}</strong><small>정가 ${won(m.originalPrice||m.price)} · 할인가 ${won(m.price)} · 재고 ${m.stock}개 · ${esc(m.surplusReason||SURPLUS_REASONS[0])}</small></div><button class="outline-button" data-action="edit" data-id="${m.id}">수정</button></div>`).join('')||'<p class="muted">오늘 등록된 메뉴가 없습니다.</p>'}</div><p class="demo-note">수정한 내용은 현재 브라우저에 저장됩니다.</p>`}
function overlay(title,body){$('#overlay').innerHTML=`<div class="overlay-bg"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="sheet-head"><h2 id="sheet-title">${title}</h2><button data-action="close" aria-label="닫기">✕</button></div>${body}</section></div>`;document.body.classList.add('modal-open');$('.sheet button,.sheet input,.sheet textarea')?.focus()}
function close(){recognition?.stop();recognition=null;pickupMapView=null;$('#overlay').innerHTML='';document.body.classList.remove('modal-open')}
function shopInfo(id){const s=shop(id);selectedShop=id;overlay(esc(s.name),`<img class="sheet-cover" src="assets/${s.image}.jpg" alt=""><div class="info-line">⌖ ${esc(s.address)} · ${esc(s.category||'골목 가게')} · ${distance(center(),s).toFixed(1)}km</div><p class="muted">가게 상세 정보는 추후 제작됩니다.</p><h3>오늘의 메뉴</h3>${active().filter(m=>m.shop===id).map(m=>`<div class="mini-item"><span>${esc(m.name)}<small>${discountPercent(m)}% 할인 · 정가 ${won(m.originalPrice||m.price)}</small></span><strong>${won(m.price)}</strong></div>`).join('')}<button class="primary" data-action="close">닫기</button>`)}
function cartSubTotal(){return state.cart.reduce((n,x)=>n+(active().find(m=>m.id===x.id)?.price||0)*x.qty,0)}
function cartSetDiscount(){if(!state.cartSet?.length||!state.cartSet.every(x=>(state.cart.find(y=>y.id===x.id)?.qty||0)>=x.qty))return 0;const setSubtotal=state.cartSet.reduce((n,x)=>n+(active().find(m=>m.id===x.id)?.price||0)*x.qty,0);return setPriceDiscount(setSubtotal)}
function cartTotal(){return cartSubTotal()-cartSetDiscount()}
function cartPage(){const rows=state.cart.map(x=>{const m=active().find(m=>m.id===x.id);return m?`<div class="cart-row"><img src="${image(m)}" alt=""><span><strong>${esc(m.name)}</strong><small>할인가 ${won(m.price)} · ${esc(shop(m.shop).name)}</small></span><div class="quantity"><button data-action="qty" data-id="${m.id}" data-value="-1" aria-label="${esc(m.name)} 수량 줄이기">−</button><b>${x.qty}</b><button data-action="qty" data-id="${m.id}" data-value="1" aria-label="${esc(m.name)} 수량 늘리기">＋</button></div></div>`:''}).join('');const setDiscount=cartSetDiscount();overlay('담은 메뉴',`${rows||'<p class="muted">담은 메뉴가 없습니다.</p>'}<div class="cart-breakdown"><span>개별 할인가 합계</span><strong>${won(cartSubTotal())}</strong></div>${setDiscount?`<div class="cart-breakdown set-discount"><span>골목 응원 할인</span><strong>−${won(setDiscount)}</strong></div>`:state.cartSet?.length?'<p class="muted">추천 조합의 모든 메뉴와 수량을 담으면 골목 응원 할인이 적용됩니다.</p>':''}<div class="cart-total"><span>최종 합계</span><strong>${won(cartTotal())}</strong></div><p class="muted">가상 상품의 주문 흐름 시연입니다. 결제와 실제 주문 전송은 이루어지지 않습니다.</p><button class="primary" data-action="order" ${!state.cart.length?'disabled':''}>데모 주문 확정 · 픽업 순서 보기</button>`)}
function pickupStops(items){const ids=[...new Set(items.map(i=>i.shop))],remaining=shops.filter(s=>ids.includes(s.id)),stops=[];let pos=center();while(remaining.length){remaining.sort((a,b)=>distance(pos,a)-distance(pos,b));const s=remaining.shift();stops.push({...s,km:distance(pos,s)});pos=s}const now=Date.now();let minutes=10;return stops.map((s,i)=>{minutes+=Math.max(5,Math.ceil(s.km*12));return {id:s.id,name:s.name,address:s.address,km:s.km,pickup:hhmm(new Date(now+minutes*60000)),items:items.filter(x=>x.shop===s.id).map(x=>x.name+' × '+x.qty)}})}
function order(){if(!state.cart.length)return;const items=[];for(const x of state.cart){const m=active().find(m=>m.id===x.id);if(!m||m.stock<x.qty){toast('재고가 변경되었습니다. 수량을 확인해 주세요.');cartPage();return}items.push({id:m.id,shop:m.shop,name:m.name,qty:x.qty,price:m.price})}const subtotal=cartSubTotal(),setDiscount=cartSetDiscount(),total=subtotal-setDiscount;if(setDiscount){const eligible=items.filter(i=>state.cartSet.some(x=>x.id===i.id)),eligibleTotal=eligible.reduce((n,i)=>n+i.price*state.cartSet.find(x=>x.id===i.id).qty,0);let remaining=setDiscount;eligible.forEach((i,index)=>{const setQty=state.cartSet.find(x=>x.id===i.id).qty;i.setDiscount=index===eligible.length-1?remaining:Math.floor(setDiscount*i.price*setQty/eligibleTotal);remaining-=i.setDiscount})}items.forEach(i=>active().find(m=>m.id===i.id).stock-=i.qty);const o={id:Date.now(),date:day()+' '+hhmm(new Date()),items,subtotal,setDiscount,total,origin:{...center()},stops:pickupStops(items)};state.orders.unshift(o);state.cart=[];state.cartSet=null;persist();close();state.mode='guest';state.tab='orders';render();route(o.id)}
function routeMapMarkup(o){const coords=[o.origin||center(),...o.stops.map(s=>shop(s.id))],lngs=coords.map(p=>p.lng),lats=coords.map(p=>p.lat),minLng=Math.min(...lngs),maxLng=Math.max(...lngs),minLat=Math.min(...lats),maxLat=Math.max(...lats),spanLng=Math.max(.004,maxLng-minLng),spanLat=Math.max(.004,maxLat-minLat),points=coords.map(p=>({x:12+76*(p.lng-minLng)/spanLng,y:85-70*(p.lat-minLat)/spanLat}));return `<div class="pickup-map" role="group" aria-label="현재 위치부터 ${o.stops.map(s=>s.name).join(', ')}까지 픽업 순서를 이은 지도"><div class="pickup-map-fallback"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><polyline points="${points.map(p=>p.x+','+p.y).join(' ')}" fill="none" stroke="#008d87" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>${points.map((p,i)=>`<span class="pickup-map-pin ${i?'':'start'}" style="left:${p.x}%;top:${p.y}%">${i||'⌖'}</span>`).join('')}</div><div id="pickup-kakao-map" class="pickup-kakao-map"></div><div class="pickup-map-controls" hidden><button data-action="route-focus" type="button">첫 가게</button><button data-action="route-overview" type="button">전체 동선</button></div></div><p class="pickup-map-caption">첫 방문 가게를 중심으로 주변 골목까지 보여줍니다. 선은 방문 순서 안내이며 실제 도로 경로는 아닙니다.</p>`}
function initRouteMap(o){const holder=$('#pickup-kakao-map');if(!holder||!window.kakao?.maps)return;kakao.maps.load(()=>{if(holder!==$('#pickup-kakao-map'))return;try{const coords=[o.origin||center(),...o.stops.map(s=>shop(s.id))],points=coords.map(p=>new kakao.maps.LatLng(p.lat,p.lng)),bounds=new kakao.maps.LatLngBounds();points.forEach(p=>bounds.extend(p));holder.style.display='block';const map=new kakao.maps.Map(holder,{center:points[1]||points[0],level:5});map.relayout();new kakao.maps.Polyline({path:points,strokeWeight:5,strokeColor:'#008d87',strokeOpacity:.9,strokeStyle:'solid',map});points.forEach((p,i)=>{new kakao.maps.Marker({position:p,map,title:i?`${i}. ${o.stops[i-1].name}`:'출발 위치'});new kakao.maps.CustomOverlay({position:p,content:`<span class="pickup-kakao-label">${i||'출발'}</span>`,yAnchor:2.1,map})});if(points.length>1)map.setBounds(bounds,45,45,45,45);const focusLevel=Math.max(1,map.getLevel()-4);map.setLevel(focusLevel);map.setCenter(points[1]||points[0]);pickupMapView={map,bounds,first:points[1]||points[0],focusLevel};holder.parentElement.querySelector('.pickup-map-controls').hidden=false}catch{holder.style.display='none';pickupMapView=null}})}
function route(id){const o=state.orders.find(x=>x.id===Number(id));if(!o)return;overlay('픽업 동선과 예상 시간',`<p class="muted">현재 위치에서 가까운 순서로 안내합니다. 예상 시간은 준비 10분과 도보 속도 기준이며 실제 상황에 따라 달라집니다.</p>${routeMapMarkup(o)}<div class="route-stops">${o.stops.map((s,i)=>`<div class="route-stop"><span class="step-circle">${i+1}</span><div><strong>${esc(s.name)}</strong><small>${esc(s.address)}</small><p>${s.items.map(esc).join(' · ')}</p></div><b>${esc(s.pickup)} 예상</b></div>`).join('')}</div><p class="demo-note">데모 주문입니다. 실제 구매·결제·픽업 예약은 발생하지 않습니다.</p><button class="primary" data-action="close">확인</button>`);requestAnimationFrame(()=>initRouteMap(o))}
function parseKoreanAmount(t){const n=t.match(/(\d[\d,]*)\s*(만|천)?\s*원/);if(!n)return null;return Number(n[1].replace(/,/g,''))*(n[2]==='만'?10000:n[2]==='천'?1000:1)}
function recommend(t){return window.MAGAM_PIPELINE.run({text:t,menus:active(),shops,origin:center(),distance,setDiscount:setPriceDiscount})}
function aiOpen(){overlay('골목 세트',`<p class="muted">AI가 인원·예산·취향에 맞춰 가까운 골목 가게의 음식 조합을 추천해요.</p><textarea id="ai-prompt" rows="3" placeholder="예: 2명이 2만원으로 먹을 수 있는 음식, 커피는 빼줘">${esc(aiText)}</textarea><button class="primary" data-action="ai-run">맞춤 조합 찾기 →</button><p class="demo-note">현재는 입력 문장을 규칙으로 분석하는 데모입니다. 외부 AI 모델은 아직 연결되지 않았습니다.</p>`)}
function aiRun(){aiText=$('#ai-prompt')?.value.trim()||'';if(!aiText){toast('원하는 조건을 입력해 주세요.');return}aiResult=recommend(aiText);const setDiscount=aiResult.discount;overlay('골목 세트 추천',`<div class="recommend-summary"><strong>${aiResult.people}명 · 예산 ${won(aiResult.budget)}</strong><p>3km 이내 골목 가게의 마감 메뉴 ${aiResult.items.length}가지를 골랐어요.</p></div>${aiResult.items.length?aiResult.items.map(x=>{const m=active().find(m=>m.id===x.id);return `<div class="mini-item"><span>${esc(m.name)} × ${x.qty}<small>${esc(shop(m.shop).name)} · ${distance(center(),shop(m.shop)).toFixed(1)}km</small></span><strong>${won(m.price*x.qty)}</strong></div>`}).join(''):'<p class="muted">조건에 맞는 조합이 없습니다. 예산이나 조건을 바꿔 주세요.</p>'}<div class="cart-breakdown"><span>개별 할인가 합계</span><strong>${won(aiResult.total)}</strong></div>${aiResult.items.length?`<div class="cart-breakdown set-discount"><span>골목 응원 ${SET_DISCOUNT_RATE}% 할인</span><strong>−${won(setDiscount)}</strong></div><p class="alley-discount-note">동네 가게 메뉴를 함께 고르면 적용되는 할인입니다. 골목 상권에 한 걸음 더 가까워지는 선택이에요.</p>`:''}<div class="cart-total"><span>추천 조합 가격</span><strong>${won(aiResult.total-setDiscount)}</strong></div><button class="primary" data-action="ai-add" ${!aiResult.items.length?'disabled':''}>추천 메뉴 담기</button><button class="outline-button full" data-action="ai-open">조건 다시 입력</button><p class="demo-note">추천은 규칙 기반 데모이며 실제 AI 모델은 아직 연결되지 않았습니다. 추천 조합의 메뉴와 수량을 유지하면 골목 응원 할인이 적용됩니다.</p>`)}
function extractDraft(t){const price=parseKoreanAmount(t),stock=Number(t.match(/(\d+)\s*(개|잔|인분|그릇)/)?.[1]||0);const h=t.match(/(?:오후\s*)?(\d{1,2})\s*시(?:\s*(\d{1,2})\s*분)?/),closing=h?String((Number(h[1])<12&&/오후/.test(t)?Number(h[1])+12:Number(h[1]))).padStart(2,'0')+':'+String(Number(h[2]||0)).padStart(2,'0'):'18:00';let name=t.replace(/예약 취소로 남은|마감 전 남은|오늘 준비한 여분/g,'').replace(/\d[\d,]*\s*(?:만|천)?\s*원/g,'').replace(/\d+\s*(?:개|잔|인분|그릇)/g,'').replace(/(?:오후\s*)?\d{1,2}\s*시(?:\s*\d{1,2}\s*분)?/g,'').replace(/(남았고|남았어요|남음|마감해요|마감|오늘|이고|입니다|이에요|이요|에|합니다)/g,' ').replace(/[,.，。]/g,' ').replace(/\s+/g,' ').trim();return {name:name.slice(0,40),price:price||0,stock,closing,shop:OWNER_SHOP_ID,desc:'',surplusReason:/취소/.test(t)?SURPLUS_REASONS[1]:/마감/.test(t)?SURPLUS_REASONS[2]:SURPLUS_REASONS[0]}}
function makeDraft(){const t=$('#product-phrase')?.value.trim();if(!photo){toast('상품 사진을 먼저 선택해 주세요.');return}if(!t){toast('상품 정보를 말하거나 입력해 주세요.');return}draft=extractDraft(t);draftView()}
function draftView(){overlay('등록 초안 확인',`<p class="muted">추출한 내용을 확인하고 필요한 부분을 고쳐 주세요.</p><img class="draft-photo" src="${photo}" alt="등록할 상품 사진"><form id="draft-form"><label class="form-label">상품 이름<input name="name" required maxlength="40" value="${esc(draft.name)}"></label><div class="form-grid"><label class="form-label">정가 (원)<input name="price" type="number" min="100" required value="${draft.price}"></label><label class="form-label">재고량<input name="stock" type="number" min="0" required value="${draft.stock}"></label></div><label class="form-label">마감시간<input name="closing" type="time" required value="${esc(draft.closing)}"></label><label class="form-label">상품 설명<textarea name="desc" rows="3" maxlength="300" placeholder="메뉴의 특징이나 보관·픽업 안내를 적어 주세요.">${esc(draft.desc||'')}</textarea><small class="desc-hint">비워 두면 “마감 상품을 판매합니다”로 표시됩니다.</small></label><p class="owner-draft-shop">등록 가게 · 오후의 빵집</p><p class="muted">등록 시 정가에서 20~30% 할인된 가격이 표시됩니다.</p><button class="primary" type="submit">확인하고 메뉴 등록하기</button></form><p class="demo-note">등록 메뉴는 현재 브라우저에만 저장됩니다.</p>`)}
function edit(id){const m=ownerMenus().find(x=>x.id===Number(id));if(!m)return;overlay('메뉴 수정',`<form id="edit-form" data-id="${m.id}"><label class="form-label">상품 이름<input name="name" required maxlength="40" value="${esc(m.name)}"></label><div class="form-grid"><label class="form-label">정가 (원)<input name="price" type="number" min="100" required value="${m.originalPrice||m.price}"></label><label class="form-label">남은 수량<input name="stock" type="number" min="0" required value="${m.stock}"></label></div><label class="form-label">마감시간<input name="closing" type="time" required value="${esc(m.closing||'18:00')}"></label><label class="form-label">상품 설명<textarea name="desc" rows="3" maxlength="300" placeholder="메뉴의 특징이나 보관·픽업 안내를 적어 주세요.">${esc(m.desc||'')}</textarea><small class="desc-hint">비워 두면 “마감 상품을 판매합니다”로 표시됩니다.</small></label><p class="muted">현재 할인율 ${discountPercent(m)}%가 정가에 적용됩니다.</p><button class="primary" type="submit">변경 저장</button></form>`)}
function dictate(){const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){toast('이 브라우저는 음성 인식을 지원하지 않습니다. 내용을 직접 입력해 주세요.');return}recognition?.stop();recognition=new SpeechRecognition();recognition.lang='ko-KR';recognition.interimResults=true;recognition.continuous=false;let finalText=$('#product-phrase')?.value.trim()||'';recognition.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){if(e.results[i].isFinal)finalText+=' '+e.results[i][0].transcript;else interim+=e.results[i][0].transcript}const field=$('#product-phrase');if(field)field.value=(finalText+' '+interim).trim()};recognition.onerror=()=>toast('음성 인식이 중단되었습니다. 직접 입력할 수 있습니다.');recognition.onend=()=>{const s=$('#mic-status');if(s)s.textContent='인식된 내용을 확인하고 초안을 만들어 주세요.'};try{recognition.start();$('#mic-status').textContent='듣고 있습니다. 상품 정보를 말씀해 주세요.'}catch{toast('마이크를 시작할 수 없습니다. 직접 입력해 주세요.')}}
function locate(){if(!navigator.geolocation){toast('이 브라우저는 위치 기능을 지원하지 않습니다.');return}navigator.geolocation.getCurrentPosition(p=>{state.location={lat:p.coords.latitude,lng:p.coords.longitude};state.locationStatus='live';state.area='';storyFilter='';persist();render();toast('현재 위치에서 3km 이내 메뉴를 표시합니다.')},()=>toast('위치를 사용할 수 없어 성수역 기본 위치를 유지합니다.'),{enableHighAccuracy:false,timeout:10000,maximumAge:300000})}
function setSettingsOpen(open){settingsOpen=open;const panel=$('#settings-panel'),button=$('[data-action="settings"]');if(panel)panel.hidden=!open;if(button)button.setAttribute('aria-expanded',String(open))}
function updateStoryArrows(){const rail=$('.stories');if(!rail)return;const prev=$('.stories-prev'),next=$('.stories-next');if(prev)prev.disabled=rail.scrollLeft<=2;if(next)next.disabled=rail.scrollLeft+rail.clientWidth>=rail.scrollWidth-2}
