function askDeleteOrder(id){const view=state.mode==='owner'?'owner':'guest',o=view==='owner'?ownerOrders().find(x=>x.id===id):state.orders.find(x=>x.id===id&&!state.customerHiddenOrderIds.includes(x.id));if(!o)return;overlay('주문 내역 삭제',`<p class="muted">주문 #${orderNumber(o)} 내역을 삭제할까요?</p><div class="delete-order-actions"><button class="outline-button" data-action="close">취소</button><button class="delete-order-confirm" data-action="confirm-delete-order" data-id="${o.id}" data-value="${view}">내역 삭제</button></div>`)}
function deleteOrder(id,view){const owner=view==='owner',guest=view==='guest';if(!owner&&!guest)return;const exists=owner?ownerOrders().some(o=>o.id===id):state.orders.some(o=>o.id===id&&!state.customerHiddenOrderIds.includes(id));if(!exists)return;const hidden=owner?state.ownerHiddenOrderIds:state.customerHiddenOrderIds;if(!hidden.includes(id))hidden.push(id);persist();close();render();toast('이 화면에서 주문 내역을 삭제했어요.')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b){if(e.target.classList.contains('overlay-bg'))close();return}const a=b.dataset.action,id=Number(b.dataset.id),v=b.dataset.value;if(a==='close')close();else if(a==='home'){state.mode='guest';state.tab='feed';render();scrollTo(0,0)}else if(a==='mode'){state.mode=state.mode==='guest'?'owner':'guest';state.tab=state.mode==='owner'?'register':'feed';persist();close();render();scrollTo(0,0)}else if(a==='tab'){state.tab=v;persist();close();render();scrollTo(0,0)}else if(a==='font-up'||a==='font-down'){state.font=Math.max(.85,Math.min(1.35,Math.round((state.font+(a==='font-up'?.1:-.1))*100)/100));persist();render()}else if(a==='speak')pageSpeech();else if(a==='story'){storyFilter=v;render();document.querySelector('.feed-list')?.scrollIntoView({behavior:'smooth',block:'start'})}else if(a==='locate')locate();else if(a==='like'){state.likes=state.likes.includes(id)?state.likes.filter(x=>x!==id):[...state.likes,id];persist();render()}else if(a==='add'){const m=active().find(x=>x.id===id),x=state.cart.find(x=>x.id===id);if(!m||m.stock<=(x?.qty||0)){toast('남은 재고를 확인해 주세요.');return}if(x)x.qty++;else state.cart.push({id,qty:1});persist();render();toast('메뉴를 담았어요.')}else if(a==='shop-products-prev'||a==='shop-products-next'){const rail=b.closest('.shop-carousel-wrap')?.querySelector('.shop-products');if(rail)rail.scrollBy({left:(a==='shop-products-next'?1:-1)*rail.clientWidth,behavior:'smooth'})}else if(a==='cart')cartPage();else if(a==='qty'){const x=state.cart.find(x=>x.id===id),m=active().find(m=>m.id===id);if(!x)return;x.qty+=Number(v);if(x.qty<=0)state.cart=state.cart.filter(y=>y.id!==id);else if(x.qty>m.stock){x.qty=m.stock;toast('남은 재고까지만 담을 수 있어요.')}persist();cartPage()}else if(a==='order')order();else if(a==='route')route(id);else if(a==='delete-order')askDeleteOrder(id);else if(a==='confirm-delete-order')deleteOrder(id,v);else if(a==='route-focus'&&pickupMapView){pickupMapView.map.setLevel(pickupMapView.focusLevel);pickupMapView.map.setCenter(pickupMapView.first)}else if(a==='route-overview'&&pickupMapView){pickupMapView.map.setBounds(pickupMapView.bounds,45,45,45,45)}else if(a==='owner-status'){const o=ownerOrders().find(x=>x.id===id),allowed={waiting:'accepted',accepted:'ready',preparing:'ready',ready:'completed'};if(o&&allowed[orderStatus(o)]===v){state.orderStatuses[o.id]=v;if(v==='completed')state.orderCompletedAt[o.id]=day()+' '+hhmm(new Date());persist();render();toast(v==='completed'?'완료 내역으로 옮겼어요.':statusLabel(v)+' 상태로 변경했어요.')}}else if(a==='shop')shopInfo(v);else if(a==='review')toast('리뷰 작성 기능은 추후 제공됩니다.');else if(a==='ai-open')aiOpen();else if(a==='ai-run')aiRun();else if(a==='ai-add'){for(const x of aiResult.items){const m=active().find(m=>m.id===x.id),inCart=state.cart.find(y=>y.id===x.id);if(m&&m.stock>=(inCart?.qty||0)+x.qty){if(inCart)inCart.qty+=x.qty;else state.cart.push({...x})}}state.cartSet=aiResult.items.every(x=>(state.cart.find(y=>y.id===x.id)?.qty||0)>=x.qty)?aiResult.items.map(x=>({...x})):null;persist();close();render();cartPage()}else if(a==='dictate')dictate();else if(a==='make-draft')makeDraft();else if(a==='edit')edit(id)});
document.addEventListener('input',e=>{if(e.target.id==='feed-search'){const pos=e.target.selectionStart;feedQuery=e.target.value;const list=$('.feed-list');if(list)list.innerHTML=visibleShopGroups().map(shopCard).join('')||'<div class="empty"><h2>검색 결과가 없어요</h2></div>';requestAnimationFrame(restoreShopCarousels);e.target.setSelectionRange(pos,pos)}if(e.target.id==='map-search'){mapQuery=e.target.value;const val=mapQuery;render();const inp=$('#map-search');inp.focus();inp.setSelectionRange(val.length,val.length)}});
document.addEventListener('change',e=>{if(e.target.id==='area-select'){state.area=e.target.value;storyFilter='';persist();render();scrollTo(0,0);return}if(e.target.id==='product-photo'){const f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024){toast('5MB 이하의 JPG, PNG, WebP 사진을 선택해 주세요.');e.target.value='';return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas'),scale=Math.min(1,900/img.width);c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);photo=c.toDataURL('image/jpeg',.78);render();toast('사진을 선택했어요.')};img.src=reader.result};reader.readAsDataURL(f)}});
document.addEventListener('submit',e=>{const f=e.target;if(!['draft-form','edit-form'].includes(f.id))return;e.preventDefault();const d=new FormData(f),name=String(d.get('name')||'').trim(),price=Number(d.get('price')),stock=Number(d.get('stock')),closing=String(d.get('closing')),desc=String(d.get('desc')||'').trim()||'마감 상품을 판매합니다';if(!name||!Number.isFinite(price)||price<100||!Number.isInteger(stock)||stock<0)return;if(f.id==='draft-form'){const menuId=Date.now();state.menus.unshift({id:menuId,shop:OWNER_SHOP_ID,name,originalPrice:price,discountRate:discountRate(menuId),price:salePrice(price,menuId),stock,closing,surplusReason:draft.surplusReason,image:photo,desc,date:day(),publishedAt:menuId,likes:0,sample:false});draft=null;photo=null;close();state.tab='manage';persist();render();toast('오늘 메뉴를 등록했어요.')}else{const m=ownerMenus().find(x=>x.id===Number(f.dataset.id));if(!m)return;Object.assign(m,{name,originalPrice:price,discountRate:discountRate(m.id),price:salePrice(price,m.id),stock,closing,desc});persist();close();render();toast('메뉴 정보를 저장했어요.')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#overlay').innerHTML)close()});
window.addEventListener('storage',e=>{if(e.key==='hangolmok-v2'&&e.newValue){try{state=JSON.parse(e.newValue);state.customerHiddenOrderIds=Array.isArray(state.customerHiddenOrderIds)?state.customerHiddenOrderIds:[];state.ownerHiddenOrderIds=Array.isArray(state.ownerHiddenOrderIds)?state.ownerHiddenOrderIds:[];render()}catch{}}});
function initMap(){
 const holder=$('#kakao-map');if(!holder||!window.kakao?.maps)return;
 kakao.maps.load(()=>{
  if(holder!==$('#kakao-map'))return;
  try{
   holder.style.display='block';
   const c=center(),position=new kakao.maps.LatLng(c.lat,c.lng);
   kakaoMap=new kakao.maps.Map(holder,{center:position,level:state.area==='all'?9:5});
   holder.parentElement.classList.add('has-map');
   if(state.area!=='all'){
    new kakao.maps.Circle({center:position,radius:3000,strokeWeight:2,strokeColor:'#e84577',strokeOpacity:.7,fillColor:'#e84577',fillOpacity:.08,map:kakaoMap});
    new kakao.maps.Marker({position,map:kakaoMap,title:state.locationStatus==='live'&&!state.area?'내 위치':state.area?'선택 지역':'성수역 기본 위치'});
   }
   const list=visibleMapShops(),bounds=new kakao.maps.LatLngBounds();
   list.forEach(s=>{const point=new kakao.maps.LatLng(s.lat,s.lng);bounds.extend(point);const marker=new kakao.maps.Marker({position:point,map:kakaoMap,title:s.name});kakao.maps.event.addListener(marker,'click',()=>shopInfo(s.id))});
   if(state.area==='all'&&list.length)kakaoMap.setBounds(bounds);
   setTimeout(()=>{if(holder===$('#kakao-map'))kakaoMap?.relayout()},0);
  }catch{holder.style.display='none';holder.parentElement.classList.remove('has-map');kakaoMap=null;toast('카카오맵을 표시하지 못해 안내 지도를 보여드려요.')}
 })
}
render();
